def solve(inputs: dict) -> float:
    X = inputs['initial_value']
    iterations = inputs['iterations']
    mask = inputs['mask']
    shifts = inputs['shifts']  # list of (op, amount) tuples: ('left', 11), ('right', 7), etc.

    for _ in range(iterations):
        for op, amount in shifts:
            if op == 'left':
                X ^= (X << amount) & mask
            else:  # right
                X ^= (X >> amount)

    return float(X & mask)

