def solve(inputs: dict) -> float:
    matrix = inputs['matrix']
    exponent = inputs['exponent']
    modulus = inputs['modulus']

    def matrix_mult(A, B, mod):
        n = len(A)
        m = len(B[0])
        k = len(B)
        C = [[0] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                for p in range(k):
                    C[i][j] = (C[i][j] + A[i][p] * B[p][j]) % mod
        return C

    def matrix_power(M, exp, mod):
        n = len(M)
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_power(matrix, exponent, modulus)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)
    return float(total % modulus)

